// Builds the subject and the HTML message for the manager. Everything that came from the employee or the image is HTML-escaped.
const e = $('Normalize Extraction').first().json;
const p = $input.first().json;
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
let reason;
if (!p.policyFound) reason = 'There is no policy row for this category.';
else if (!p.eurKnown) reason = 'The currency ' + esc(e.currency || 'unknown') + ' cannot be compared with the EUR policy.';
else reason = 'The amount ' + Number(e.totalEur).toFixed(2) + ' EUR is above the automatic approval limit of ' + p.autoLimitEur + ' EUR for ' + esc(e.category) + '.';
const message = '<b>An expense needs your decision.</b><br><br>'
  + 'Employee: ' + esc(e.employeeName) + ' (' + esc(e.employeeEmail) + '), ' + esc(e.department) + '<br>'
  + 'Merchant: <b>' + esc(e.merchant) + '</b><br>'
  + 'Date: ' + esc(e.expenseDate) + '<br>'
  + 'Total: <b>' + Number(e.total).toFixed(2) + ' ' + esc(e.currency) + '</b> (about ' + Number(e.totalEur).toFixed(2) + ' EUR)<br>'
  + 'Category: ' + esc(e.category) + '<br>'
  + 'Receipt number: ' + esc(e.receiptNumber || '-') + '<br>'
  + 'Reference: ' + esc(e.submissionId) + '<br><br>'
  + 'Why you are asked: ' + reason + '<br><br>'
  + 'Open the form, choose Approve or Reject, enter the approved amount (in ' + esc(e.currency) + ') and an optional comment. The receipt photo is not attached to this e-mail.';
return [{ json: { managerSubject: '[Expense approval] ' + e.employeeName + ' - ' + e.merchant + ' ' + Number(e.total).toFixed(2) + ' ' + e.currency, managerMessage: message } }];
